# --- what to ask for (pure, tested in the repo) -------------------------------


def _round16(value: float) -> int:
    return int(round(value / 16) * 16)


def i2v_geometry(width: int, height: int) -> tuple[tuple[int, int, int, int], tuple[int, int]]:
    """Crop box and output size for an i2v still, as the i2v Space's resize_image does."""
    max_dim, min_dim, square = 832, 480, 640
    if width == height:
        return (0, 0, width, height), (square, square)
    aspect = width / height
    box = (0, 0, width, height)
    if aspect > max_dim / min_dim:
        target_w, target_h = max_dim, min_dim
        crop = int(round(height * max_dim / min_dim))
        left = (width - crop) // 2
        box = (left, 0, left + crop, height)
    elif aspect < min_dim / max_dim:
        target_w, target_h = min_dim, max_dim
        crop = int(round(width / (min_dim / max_dim)))
        top = (height - crop) // 2
        box = (0, top, width, top + crop)
    elif width > height:
        target_w, target_h = max_dim, int(round(max_dim / aspect))
    else:
        target_h, target_w = max_dim, int(round(max_dim * aspect))
    size = (max(min_dim, min(max_dim, _round16(target_w))), max(min_dim, min(max_dim, _round16(target_h))))
    return box, size


def first_last_size(width: int, height: int) -> tuple[int, int]:
    """Output size for first-last stills, as the first-last Space's process_image_for_video does."""
    max_dim, min_dim, square = 832, 480, 480
    if width == height:
        return square, square
    aspect = width / height
    w, h = float(width), float(height)
    if w > max_dim or h > max_dim:
        scale = max_dim / w if aspect > 1 else max_dim / h
        w, h = w * scale, h * scale
    if w < min_dim or h < min_dim:
        scale = min_dim / h if aspect > 1 else min_dim / w
        w, h = w * scale, h * scale
    final_w, final_h = _round16(w), _round16(h)
    final_w = max(final_w, min_dim if aspect < 1 else square)
    final_h = max(final_h, min_dim if aspect > 1 else square)
    return final_w, final_h


def frame_count(mode: str, seconds: float) -> int:
    """Frames to ask for (4k + 1, as Wan needs): the Spaces' rules at 16 fps."""
    frames = int(round(seconds * FPS))
    if mode == "i2v":
        return 1 + min(max(frames, 8), 80)
    frames = min(max(frames, 8), 81)
    return frames if frames % 4 == 1 else frames // 4 * 4 + 1


def sigmas(steps: int, shift: float) -> list[float]:
    """The noise level at each step: linear from 1, time-shifted (flow matching)."""
    out = []
    for i in range(steps):
        s = 1 - i / steps
        out.append(shift * s / (1 + (shift - 1) * s))
    return out


def switch_step(steps: int, shift: float, boundary: float = BOUNDARY) -> int:
    """The first step the low-noise expert takes: steps at or above the boundary go to the high-noise one."""
    high = sum(1 for sigma in sigmas(steps, shift) if sigma >= boundary - 1e-9)
    return min(max(high, 1), steps - 1)


def _conditioning(job: dict, files: dict, still_names: list[str], size: tuple[int, int], frames: int) -> dict:
    """The nodes both phases share: text encoder, VAE, the still(s), and the Wan conditioning (node "cond")."""
    graph = {
        "clip": {"class_type": "CLIPLoader", "inputs": {"clip_name": files["text"], "type": "wan"}},
        "pos": {"class_type": "CLIPTextEncode", "inputs": {"text": job.get("prompt") or "", "clip": ["clip", 0]}},
        "neg": {"class_type": "CLIPTextEncode", "inputs": {"text": job.get("negative_prompt") or "", "clip": ["clip", 0]}},
        "vae": {"class_type": "VAELoader", "inputs": {"vae_name": files["vae"]}},
        "first": {"class_type": "LoadImage", "inputs": {"image": still_names[0]}},
    }
    common = {"positive": ["pos", 0], "negative": ["neg", 0], "vae": ["vae", 0], "width": size[0],
              "height": size[1], "length": frames, "batch_size": 1, "start_image": ["first", 0]}
    if job["mode"] == "i2v":
        graph["cond"] = {"class_type": "WanImageToVideo", "inputs": common}
    else:
        graph["last"] = {"class_type": "LoadImage", "inputs": {"image": still_names[1]}}
        graph["cond"] = {"class_type": "WanFirstLastFrameToVideo", "inputs": {**common, "end_image": ["last", 0]}}
    return graph


def _expert(role: str, files: dict, strength: float, shift: float) -> dict:
    return {
        f"{role}_unet": {"class_type": "UnetLoaderGGUF", "inputs": {"unet_name": files[role]}},
        f"{role}_lora": {"class_type": "LoraLoaderModelOnly",
                         "inputs": {"model": [f"{role}_unet", 0], "lora_name": files["lora"], "strength_model": strength}},
        f"{role}_model": {"class_type": "ModelSamplingSD3", "inputs": {"model": [f"{role}_lora", 0], "shift": shift}},
    }


def _sampler(role: str, job: dict, profile: dict, start: int, end: int, *, add_noise: bool, leftover: bool, latent) -> dict:
    return {"class_type": "KSamplerAdvanced", "inputs": {
        "model": [f"{role}_model", 0], "add_noise": "enable" if add_noise else "disable",
        "noise_seed": int(job["seed"]), "steps": int(job["steps"]), "cfg": 1.0,
        "sampler_name": profile["sampler"], "scheduler": "simple",
        "positive": ["cond", 0], "negative": ["cond", 1], "latent_image": latent,
        "start_at_step": start, "end_at_step": end,
        "return_with_leftover_noise": "enable" if leftover else "disable",
    }}


def high_graph(job: dict, files: dict, still_names: list[str], size, frames: int, prefix: str) -> dict:
    """Phase 1: the high-noise expert's steps, saved as a latent (ComfyUI API format)."""
    profile = PROFILES[job["mode"]]
    switch = switch_step(int(job["steps"]), profile["shift"])
    graph = _conditioning(job, files, still_names, size, frames)
    graph.update(_expert("high", files, LORA_HIGH, profile["shift"]))
    graph["sample"] = _sampler("high", job, profile, 0, switch, add_noise=True, leftover=True, latent=["cond", 2])
    graph["save"] = {"class_type": "SaveLatent", "inputs": {"samples": ["sample", 0], "filename_prefix": prefix}}
    return graph


def low_graph(job: dict, files: dict, still_names: list[str], size, frames: int, latent_name: str, prefix: str) -> dict:
    """Phase 2: the low-noise expert's steps from the saved latent, decoded to frames."""
    profile = PROFILES[job["mode"]]
    switch = switch_step(int(job["steps"]), profile["shift"])
    graph = _conditioning(job, files, still_names, size, frames)
    graph.update(_expert("low", files, LORA_LOW, profile["shift"]))
    graph["latent"] = {"class_type": "LoadLatent", "inputs": {"latent": latent_name}}
    graph["sample"] = _sampler("low", job, profile, switch, 10000, add_noise=False, leftover=False, latent=["latent", 0])
    graph["decode"] = {"class_type": "VAEDecode", "inputs": {"samples": ["sample", 0], "vae": ["vae", 0]}}
    graph["save"] = {"class_type": "SaveImage", "inputs": {"images": ["decode", 0], "filename_prefix": prefix}}
    return graph


def edit_size(width: int, height: int) -> tuple[int, int]:
    """An intermediate keyframe's size: always the keyframe canvas (stills of another size are resized to it)."""
    return EDIT_SIZE


def edit_graph(job: dict, files: dict, still_names: list[str], size, prefix: str) -> dict:
    """An intermediate keyframe (ComfyUI API format): both stills as references, from the init still, re-drawn by denoise.

    `still_names`: the first still (Picture 1), the last (Picture 2) and the init still the latent starts from."""
    edit = job.get("edit") or {}
    graph = {
        "unet": {"class_type": "UnetLoaderGGUF", "inputs": {"unet_name": files["edit"]}},
        "model": {"class_type": "ModelSamplingAuraFlow", "inputs": {"model": ["unet", 0], "shift": EDIT_SHIFT}},
        "clip": {"class_type": "CLIPLoader", "inputs": {"clip_name": files["edit_text"], "type": "qwen_image"}},
        "vae": {"class_type": "VAELoader", "inputs": {"vae_name": files["edit_vae"]}},
        "first": {"class_type": "LoadImage", "inputs": {"image": still_names[0]}},
        "last": {"class_type": "LoadImage", "inputs": {"image": still_names[1]}},
        "init": {"class_type": "LoadImage", "inputs": {"image": still_names[2]}},
        "start": {"class_type": "VAEEncode", "inputs": {"pixels": ["init", 0], "vae": ["vae", 0]}},
    }
    for node, text in (("pos", job.get("prompt") or ""), ("neg", job.get("negative_prompt") or "")):
        graph[node] = {"class_type": "TextEncodeQwenImageEditPlus", "inputs": {
            "clip": ["clip", 0], "prompt": text, "vae": ["vae", 0], "image1": ["first", 0], "image2": ["last", 0]}}
    graph["sample"] = {"class_type": "KSampler", "inputs": {
        "model": ["model", 0], "seed": int(job["seed"]), "steps": int(job["steps"]), "cfg": float(edit.get("cfg", 2.5)),
        "sampler_name": "euler", "scheduler": "simple", "positive": ["pos", 0], "negative": ["neg", 0],
        "latent_image": ["start", 0], "denoise": float(edit.get("denoise", 0.7)),
    }}
    graph["decode"] = {"class_type": "VAEDecode", "inputs": {"samples": ["sample", 0], "vae": ["vae", 0]}}
    graph["save"] = {"class_type": "SaveImage", "inputs": {"images": ["decode", 0], "filename_prefix": prefix}}
    return graph


def load_jobs(here: Path | None = None) -> dict:
    """The job list: jobs.json next to this script, else the one written into JOBS_JSON."""
    if here is None:
        here = Path(__file__).resolve().parent if "__file__" in globals() else Path.cwd()
    path = here / "jobs.json"
    if path.is_file():
        return json.loads(path.read_text(encoding="utf-8"))
    if JOBS_JSON:
        return json.loads(base64.b64decode(JOBS_JSON).decode("utf-8"))
    raise SystemExit("no job list: neither jobs.json nor JOBS_JSON")


# --- running on Kaggle ---------------------------------------------------------

_LOG_LOCK = threading.Lock()
_T0 = time.time()


def log(message: str) -> None:
    line = f"[{time.time() - _T0:7.1f}s] {message}"
    with _LOG_LOCK:
        print(line, flush=True)
        with open(OUT / "run.log", "a", encoding="utf-8") as f:
            f.write(line + "\n")


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def sh(cmd: list[str], **kw) -> subprocess.CompletedProcess:
    result = subprocess.run(cmd, capture_output=True, text=True, **kw)
    if result.returncode != 0:
        raise RuntimeError(f"{' '.join(cmd[:4])} failed: {(result.stderr or result.stdout)[-2000:]}")
    return result


def work_dir() -> Path:
    """The roomiest scratch disk (models ~30 GB; /kaggle/working is the 20 GB output)."""
    best, room = None, -1
    for candidate in ("/kaggle/tmp", "/tmp", "/root"):
        path = Path(candidate)
        try:
            path.mkdir(parents=True, exist_ok=True)
            free = shutil.disk_usage(path).free
        except OSError:
            continue
        if free > room:
            best, room = path, free
    if best is None or room < 36e9:
        raise RuntimeError(f"not enough disk for the models: {room / 1e9:.0f} GB free in {best}")
    log(f"work dir {best}: {room / 1e9:.0f} GB free")
    return best / "menga"


def fetch_tar(url: str, into: Path) -> None:
    into.mkdir(parents=True, exist_ok=True)
    archive = into.with_suffix(".tar.gz")
    urllib.request.urlretrieve(url, archive)
    with tarfile.open(archive) as tar:
        top = tar.getnames()[0].split("/")[0]
        if hasattr(tarfile, "data_filter"):
            tar.extractall(into.parent, filter="data")
        else:
            tar.extractall(into.parent)
    shutil.rmtree(into)
    (into.parent / top).rename(into)
    archive.unlink()


def install_comfyui(root: Path) -> Path:
    comfy = root / "ComfyUI"
    fetch_tar(COMFYUI["url"], comfy)
    fetch_tar(GGUF_NODE["url"], comfy / "custom_nodes" / "ComfyUI-GGUF")
    keep = [line.strip() for line in (comfy / "requirements.txt").read_text().splitlines()
            if line.strip() and not line.startswith("#") and line.split("=")[0].split(">")[0].strip()
            not in ("torch", "torchvision", "torchaudio")]
    keep += ["gguf>=0.13.0", "sentencepiece", "protobuf"]
    pip = [sys.executable, "-m", "pip", "install", "-q", "--disable-pip-version-check"]
    try:
        sh(pip + keep)
    except RuntimeError as err:  # one by one, so an optional extra cannot block the rest
        log(f"pip (all at once) failed, one by one: {str(err)[-300:]}")
        for req in keep:
            try:
                sh(pip + [req])
            except RuntimeError as one:
                log(f"pip {req} failed: {str(one)[-300:]}")
    return comfy


def download_models(dest: Path, models: dict | None = None, resolved: dict | None = None) -> dict:
    """Download the model files in parallel into dest/<ComfyUI folder>/; return role -> file name.

    `models`: role -> (repo, revision, file, folder), MODELS by default; a revision None is resolved to the
    repo's current commit, written into `resolved` (role -> repo@commit/file) for the manifest."""
    models = MODELS if models is None else models
    sh([sys.executable, "-m", "pip", "install", "-q", "--disable-pip-version-check", "-U", "huggingface_hub", "hf_xet", "hf_transfer"])
    os.environ.setdefault("HF_HUB_ENABLE_HF_TRANSFER", "1")
    os.environ.setdefault("HF_XET_HIGH_PERFORMANCE", "1")
    from huggingface_hub import hf_hub_download  # type: ignore[import-not-found]  # noqa: PLC0415

    files, errors = {}, []

    def one(role: str) -> None:
        repo, revision, name, folder = models[role]
        t = time.time()
        try:
            if revision is None:  # not pinned yet: fetch the current commit, and record which it was
                from huggingface_hub import HfApi  # type: ignore[import-not-found]  # noqa: PLC0415

                revision = HfApi().model_info(repo).sha or "main"
            if resolved is not None:
                resolved[role] = f"{repo}@{revision}/{name}"
            got = Path(hf_hub_download(repo, name, revision=revision, local_dir=dest / "_hf" / role))
            target = dest / folder / Path(name).name
            target.parent.mkdir(parents=True, exist_ok=True)
            got.rename(target)
            files[role] = target.name
            log(f"model {role}: {repo}@{revision[:7]}/{name} {target.stat().st_size / 1e9:.1f} GB in {time.time() - t:.0f}s")
        except Exception as err:  # noqa: BLE001 - reported below
            errors.append(f"{role}: {err}")

    threads = [threading.Thread(target=one, args=(role,)) for role in models]
    for th in threads:
        th.start()
    for th in threads:
        th.join()
    if errors:
        raise RuntimeError("model download failed: " + "; ".join(errors))
    return files


def gpus() -> list[str]:
    try:
        lines = sh(["nvidia-smi", "-L"]).stdout.strip().splitlines()
    except (RuntimeError, FileNotFoundError):
        return []
    return [line.strip() for line in lines if line.startswith("GPU")]


class InfraError(RuntimeError):
    """A step lost to the run's infrastructure, not to the model: kind "server" (it died or stopped answering)
    or "timeout"."""

    def __init__(self, message: str, kind: str = "server"):
        super().__init__(message)
        self.kind = kind


def host_ram_gb() -> float | None:
    """The host's available RAM (MemAvailable), in GB; None where /proc/meminfo is not there."""
    try:
        for line in Path("/proc/meminfo").read_text().splitlines():
            if line.startswith("MemAvailable:"):
                return int(line.split()[1]) / 1e6
    except (OSError, ValueError, IndexError):
        pass
    return None


def _gb(value: float | None) -> str:
    return "?" if value is None else f"{value:.1f} GB"


def sampling_started(log_text: str) -> bool:
    """True once ComfyUI's log shows a sampler's progress bar (`| 0/4 [`): the graph's models are loaded."""
    return bool(re.search(r"\|\s*\d+/\d+ \[", log_text))


# One model load at a time on the host (run 2026-11-08-night: the servers were killed while loading models,
# three times while both loaded at once). A graph holds the gate from its submission until its sampler starts.
HOST_GATE = threading.Lock()
GATE_LIMIT = 300.0  # longest a graph holds the gate before its sampler shows progress


class Worker:
    """One ComfyUI server on one GPU."""

    def __init__(self, index: int, comfy: Path, root: Path, input_dir: Path | None = None):
        self.index = index
        self.port = PORT + index
        self.comfy = comfy
        self.restarts = 0
        self.phase: str | None = None  # the expert its server has loaded: "high", "low" or None
        self.ram_min: float | None = None  # the lowest host RAM seen while its last graph ran
        self.input = input_dir or root / f"in{index}"
        self.output = root / f"out{index}"
        self.input.mkdir(parents=True, exist_ok=True)
        self.output.mkdir(parents=True, exist_ok=True)
        self.log_path = root / f"comfyui{index}.log"
        self.log_file = open(self.log_path, "w")
        self.start()

    def start(self) -> None:
        comfy, index = self.comfy, self.index
        self.proc = subprocess.Popen(
            [sys.executable, "main.py", "--listen", "127.0.0.1", "--port", str(self.port), "--cuda-device", str(index),
             "--input-directory", str(self.input), "--output-directory", str(self.output), "--disable-auto-launch",
             "--preview-method", "none"],
            cwd=comfy, stdout=self.log_file, stderr=subprocess.STDOUT,
        )

    def url(self, path: str) -> str:
        return f"http://127.0.0.1:{self.port}{path}"

    def dead(self) -> bool:
        return self.proc.poll() is not None

    def died(self) -> InfraError:
        code = self.proc.returncode
        how = f"exit {code}" + (": killed (SIGKILL), most likely out of host RAM" if code == -9 else "")
        return InfraError(f"ComfyUI {self.index} died ({how}; host RAM {_gb(host_ram_gb())} free now, "
                          f"lowest seen {_gb(self.ram_min)})", "server")

    def call(self, path: str, data: dict | None = None, timeout: float = 60):
        body = None if data is None else json.dumps(data).encode()
        request = urllib.request.Request(self.url(path), data=body, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                text = response.read().decode()
        except urllib.error.HTTPError as err:
            raise RuntimeError(f"ComfyUI {path}: HTTP {err.code}: {err.read().decode()[:2000]}") from err
        return json.loads(text) if text.strip() else {}

    def wait_ready(self, limit: float = 600) -> None:
        start = time.time()
        while time.time() - start < limit:
            if self.dead():
                raise InfraError(f"ComfyUI {self.index} exited: see comfyui{self.index}.log")
            try:
                self.call("/system_stats", timeout=5)
                return
            except (OSError, RuntimeError):
                time.sleep(2)
        raise InfraError(f"ComfyUI {self.index} did not start in {limit:.0f}s")

    def _log_since(self, offset: int) -> str:
        try:
            with open(self.log_path, "rb") as f:
                f.seek(offset)
                return f.read().decode(errors="replace")
        except OSError:
            return ""

    def run(self, graph: dict, limit: float = 3600, gate: threading.Lock | None = None) -> dict:
        """Queue one graph and wait for it; return its outputs.

        The host gate is held while the graph loads its models (until its sampler shows progress, at most
        GATE_LIMIT); the lowest host RAM seen while it runs is kept in ram_min."""
        gate = HOST_GATE if gate is None else gate
        self.log_file.flush()
        offset = self.log_path.stat().st_size if self.log_path.is_file() else 0
        gate.acquire()
        held, gated_at = True, time.time()
        self.ram_min = host_ram_gb()
        try:
            prompt_id = self.call("/prompt", {"prompt": graph, "client_id": f"menga{self.index}"})["prompt_id"]
            start = time.time()
            while time.time() - start < limit:
                time.sleep(2)
                ram = host_ram_gb()
                if ram is not None and (self.ram_min is None or ram < self.ram_min):
                    self.ram_min = ram
                if held and (time.time() - gated_at > GATE_LIMIT or sampling_started(self._log_since(offset))):
                    gate.release()
                    held = False
                if self.dead():
                    raise self.died()
                history = self.call(f"/history/{prompt_id}", timeout=30).get(prompt_id)
                if not history:
                    continue
                status = history.get("status") or {}
                if status.get("status_str") == "error":
                    messages = [m for m in status.get("messages", []) if m and m[0] == "execution_error"]
                    detail = messages[-1][1] if messages else status
                    if isinstance(detail, dict):
                        detail = f"{detail.get('node_type')}: {detail.get('exception_message', '').strip()}"
                    raise RuntimeError(f"ComfyUI error: {detail}")
                if status.get("completed"):
                    return history.get("outputs", {})
            raise InfraError(f"timed out after {limit:.0f}s", "timeout")
        finally:
            if held:
                gate.release()

    def free(self) -> None:
        """Unload the models and drop ComfyUI's cache: the next graph loads its expert from disk."""
        self.call("/free", {"unload_models": True, "free_memory": True})
        time.sleep(8)
        self.phase = None

    def restart(self) -> None:
        """A new server on the same GPU; latents already saved in the input folder stay usable."""
        self.restarts += 1
        self.stop()
        self.log_file.write(f"\n--- menga: restarting ComfyUI {self.index} (restart {self.restarts}; "
                            f"host RAM {_gb(host_ram_gb())} free) ---\n")
        self.log_file.flush()
        self.phase = None
        self.start()
        self.wait_ready()

    def stop(self) -> None:
        if self.proc.poll() is None:
            self.proc.terminate()
            try:
                self.proc.wait(30)
            except subprocess.TimeoutExpired:
                self.proc.kill()
                self.proc.wait(30)


def fetch_still(url: str):
    from PIL import Image  # noqa: PLC0415 - Kaggle has Pillow
    import io  # noqa: PLC0415

    with urllib.request.urlopen(url, timeout=60) as response:
        return Image.open(io.BytesIO(response.read())).convert("RGB")


def prepare_stills(job: dict, folder: Path) -> tuple[list[str], tuple[int, int]]:
    """Download the job's still(s) and size them as its mode's Space would; return file names and the size."""
    from PIL import Image  # noqa: PLC0415

    images = [fetch_still(url) for url in job["stills"]]
    if job["mode"] == "i2v":
        box, size = i2v_geometry(*images[0].size)
        images = [images[0].crop(box).resize(size, Image.Resampling.LANCZOS)]
    else:
        size = first_last_size(*images[0].size)
        first = images[0].resize(size, Image.Resampling.LANCZOS)
        last = images[1]
        scale = max(size[0] / last.width, size[1] / last.height)
        last = last.resize((int(last.width * scale), int(last.height * scale)), Image.Resampling.LANCZOS)
        left, top = (last.width - size[0]) // 2, (last.height - size[1]) // 2
        images = [first, last.crop((left, top, left + size[0], top + size[1]))]
    names = []
    for label, image in zip(("first", "last"), images):
        name = f"{job['clip']}-{label}.png"
        image.save(folder / name)
        names.append(name)
    return names, size


def prepare_edit_stills(job: dict, folder: Path) -> tuple[list[str], tuple[int, int]]:
    """Download an image-edit job's two stills, size them to the canvas, and make the init still; return names and size."""
    from PIL import Image  # noqa: PLC0415

    first, last = (fetch_still(url) for url in job["stills"][:2])
    size = edit_size(*first.size)
    first, last = (im.resize(size, Image.Resampling.LANCZOS) if im.size != size else im for im in (first, last))
    init = first if (job.get("edit") or {}).get("init") == "first" else Image.blend(first, last, 0.5)
    names = []
    for label, image in (("first", first), ("last", last), ("init", init)):
        name = f"{job['clip']}-{label}.png"
        image.save(folder / name)
        names.append(name)
    return names, size


def run_edits(worker: "Worker", jobs: list[dict], files: dict, manifest: "Manifest") -> None:
    """Every image-edit job on this worker, one after the other: <clip>.png in the output."""
    for job in jobs:
        rec = job["_record"]
        rec["gpu"] = worker.index
        try:
            names, size = prepare_edit_stills(job, worker.input)
        except Exception as err:  # noqa: BLE001 - the stills never reached the model
            rec.update(ok=False, error=f"could not read the still(s): {err}", error_kind="input", finished_at=now_iso())
            log(f"{job['clip']}: still failed: {err}")
            manifest.save()
            continue
        rec.update(width=size[0], height=size[1], edit=job.get("edit"))
        t = time.time()
        try:
            graph = edit_graph(job, files, names, size, f"mids/{job['clip']}")
            outputs = on_server(worker, job, "image edit", lambda: worker.run(graph))
            image = outputs["save"]["images"][0]
            path = worker.output / image.get("subfolder", "") / image["filename"]
            if blank([path]):
                raise RuntimeError("the decoded image is blank (fp16 overflow?)")
            shutil.copyfile(path, OUT / f"{job['clip']}.png")
            rec.update(ok=True, file=f"{job['clip']}.png", finished_at=now_iso())
            log(f"{job['clip']}: intermediate keyframe done in {time.time() - t:.0f}s")
        except Exception as err:  # noqa: BLE001
            rec.update(ok=False, error=str(err), error_kind=infra_kind(err, worker) or "generation", finished_at=now_iso())
            log(f"{job['clip']}: image edit failed: {err}")
        rec["seconds"] = round(time.time() - t, 1)
        manifest.save()


def link_models(comfy: Path, models_root: Path, models: dict) -> None:
    for folder in {m[3] for m in models.values()}:
        target = comfy / "models" / folder
        target.mkdir(parents=True, exist_ok=True)
        for f in (models_root / folder).iterdir():
            if not (target / f.name).exists():
                (target / f.name).symlink_to(f)


def drop_models(comfy: Path, models_root: Path, files: dict, models: dict) -> None:
    """Delete downloaded model files (and their links), to make room on disk for the next ones."""
    for role, name in files.items():
        folder = models[role][3]
        (comfy / "models" / folder / name).unlink(missing_ok=True)
        (models_root / folder / name).unlink(missing_ok=True)
    shutil.rmtree(models_root / "_hf", ignore_errors=True)


def ffmpeg() -> str:
    found = shutil.which("ffmpeg")
    if found:
        return found
    sh([sys.executable, "-m", "pip", "install", "-q", "imageio-ffmpeg"])
    import imageio_ffmpeg  # type: ignore[import-untyped]  # noqa: PLC0415

    return imageio_ffmpeg.get_ffmpeg_exe()


def encode(frames: list[Path], out: Path) -> None:
    listing = out.with_suffix(".txt")
    listing.write_text("".join(f"file '{f}'\nduration {1 / FPS}\n" for f in frames))
    sh([ffmpeg(), "-y", "-loglevel", "error", "-r", str(FPS), "-f", "concat", "-safe", "0", "-i", str(listing),
        "-r", str(FPS), "-c:v", "libx264", "-crf", "16", "-pix_fmt", "yuv420p", "-an", str(out)])
    listing.unlink()


def blank(frames: list[Path]) -> bool:
    """True when the decoded frames are all near-black (fp16 overflow gives black or NaN frames)."""
    from PIL import Image, ImageStat  # noqa: PLC0415

    sample = frames[:: max(1, len(frames) // 4)]
    return all(max(ImageStat.Stat(Image.open(f).convert("L")).mean) < 8 for f in sample)


class Manifest:
    def __init__(self, data: dict):
        self.data = data
        self.lock = threading.Lock()

    def save(self) -> None:
        with self.lock:
            (OUT / "manifest.json").write_text(json.dumps(self.data, ensure_ascii=False, indent=1), encoding="utf-8")


# --- surviving the infrastructure (kernel v5; pure, tested in the repo) ----------
#
# Run 2026-11-08-night (v3): the ComfyUI servers were killed six times in 65 min, each time 30-110 s into a new
# graph (while it loads its models), three times both servers at once, with no Python error in their logs:
# killed from outside, by the host's memory (two servers, each with a 14B expert, the 6.4 GB text encoder and
# the LoRA). v3 allowed 3 restarts per server for the whole run; after that every remaining job failed at once.

MAX_TRIES = 3  # per job: steps lost to the infrastructure before the job goes back to the queue (not an attempt)
RESTART_TRIES = 3  # failed restarts in a row before a worker gives its GPU up (its jobs go to the others)
RESTART_PAUSE = 20.0  # seconds before a restart is tried again (times the try)
SOLO_DEATHS, SOLO_WINDOW = 3, 1800.0  # this many server deaths within this many seconds: one ComfyUI from then on
SESSION_CAP_HOURS = 11.5  # Kaggle ends a session at 12 h
ESTIMATES = {"high": 400.0, "low": 760.0}  # seconds per step until the run has timed its own (run 2026-11-08-night)
INFRA_TEXT = re.compile(
    r"Connection (refused|reset|aborted)|Broken pipe|Remote end closed|RemoteDisconnected|IncompleteRead"
    r"|ComfyUI \d+ (died|exited|did not start)",
    re.IGNORECASE,
)


def infra_kind(err: BaseException, worker) -> str | None:
    """"server" or "timeout" when a step was lost to the infrastructure (the server died or stopped answering,
    a connection broke, the step timed out), None for a real error of the model or its output."""
    if isinstance(err, InfraError):
        return err.kind
    if isinstance(err, TimeoutError) or "timed out" in str(err):
        return "timeout"
    if worker.dead() or isinstance(err, ConnectionError) or INFRA_TEXT.search(str(err)):
        return "server"
    if isinstance(err, urllib.error.URLError) and not isinstance(err, urllib.error.HTTPError):
        return "server"
    return None


class Task:
    def __init__(self, job: dict, phase: str):
        self.job, self.phase = job, phase


class Work:
    """The run's clips, shared by the workers: every high-noise step first (any GPU), then the low-noise steps
    (any GPU: the latents are in the shared input folder). A step lost to the infrastructure goes back to the
    front of its list, up to MAX_TRIES per job; no step starts that cannot finish before the deadline."""

    def __init__(self, jobs: list[dict], workers: list[int], deadline: float, save=None, clock=time.time):
        self.cond = threading.Condition()
        self.highs = list(jobs)
        self.lows: list[dict] = []
        self.busy: dict[int, Task] = {}
        self.alive = set(workers)
        self.deadline, self.clock = deadline, clock
        self.save = save or (lambda: None)
        self.solo = False
        self.deaths: list[float] = []
        self.timed: dict[str, list[float]] = {"high": [], "low": []}

    def estimate(self, phase: str) -> float:
        seen = self.timed[phase]
        return sum(seen) / len(seen) if seen else ESTIMATES[phase]

    def _end(self, job: dict, why: str) -> None:
        job["_record"].update(ok=False, error=why, error_kind="session", finished_at=now_iso())
        log(f"{job['clip']}: {why}")

    def _next(self) -> Task | None:
        now, hours = self.clock(), (self.deadline - _T0) / 3600
        gpus = max(1, 1 if self.solo else len(self.alive))
        if self.highs:  # a high-noise step only if its low-noise step, and those already owed, still fit
            owed = len(self.lows) + sum(1 for t in self.busy.values() if t.phase == "high")
            if now + self.estimate("high") + self.estimate("low") * (1 + owed / gpus) <= self.deadline:
                return Task(self.highs.pop(0), "high")
            for job in self.highs:
                self._end(job, f"not started: the run's {hours:g} h would end before it finished")
            self.highs = []
            self.save()
        while self.lows:
            if now + self.estimate("low") <= self.deadline:
                return Task(self.lows.pop(0), "low")
            self._end(self.lows.pop(0), f"low-noise steps not started: the run's {hours:g} h would end first")
            self.save()
        return None

    def take(self, index: int) -> Task | None:
        """The worker's next step; waits while other workers' steps may still bring work; None: stop."""
        with self.cond:
            while True:
                if index not in self.alive:
                    return None
                if self.solo and index != min(self.alive):
                    self.alive.discard(index)
                    log(f"ComfyUI {index}: stopped for the rest of the run (one server on the host)")
                    self.cond.notify_all()
                    return None
                task = self._next()
                if task is not None:
                    self.busy[index] = task
                    return task
                if not self.busy:
                    return None
                self.cond.wait(5)

    def done(self, index: int, task: Task, seconds: float, file: str | None = None) -> None:
        with self.cond:
            self.busy.pop(index, None)
            self.timed[task.phase].append(seconds)
            rec = task.job["_record"]
            if task.phase == "high":
                rec["high_seconds"] = round(seconds, 1)
                self.lows.append(task.job)
                log(f"{task.job['clip']}: high-noise steps done in {seconds:.1f}s on GPU {index}")
            else:
                rec.update(low_seconds=round(seconds, 1), ok=True, file=file, finished_at=now_iso())
                rec["seconds"] = round(rec.get("high_seconds", 0) + seconds, 1)
                log(f"{task.job['clip']}: done, low-noise + decode {seconds:.1f}s on GPU {index}")
            self.save()
            self.cond.notify_all()

    def failed(self, index: int, task: Task, err: BaseException, seconds: float, kind: str = "generation") -> None:
        """A real error (of the model, its output or its still): recorded as it is, not retried here."""
        with self.cond:
            self.busy.pop(index, None)
            rec = task.job["_record"]
            rec.update(ok=False, error=str(err), error_kind=kind, finished_at=now_iso())
            rec[f"{task.phase}_seconds"] = round(seconds, 1)
            rec["seconds"] = round(rec.get("high_seconds", 0) + rec.get("low_seconds", 0), 1)
            log(f"{task.job['clip']}: {task.phase}-noise phase failed: {err}")
            self.save()
            self.cond.notify_all()

    def lost(self, index: int, task: Task, err: BaseException, kind: str, seconds: float) -> None:
        """A step lost to the infrastructure: back to the front of its list, or handed back after MAX_TRIES."""
        with self.cond:
            self.busy.pop(index, None)
            rec = task.job["_record"]
            rec.setdefault("retries", []).append(f"{task.phase}: {err}")
            rec["lost_seconds"] = round(rec.get("lost_seconds", 0) + seconds, 1)
            if len(rec["retries"]) < MAX_TRIES:
                (self.highs if task.phase == "high" else self.lows).insert(0, task.job)
                log(f"{task.job['clip']}: {task.phase}-noise steps lost on GPU {index} ({err}); will try again")
            else:
                rec.update(ok=False, error=f"gave up after {MAX_TRIES} tries: {err}", error_kind=kind,
                           finished_at=now_iso())
                log(f"{task.job['clip']}: {task.phase}-noise steps lost {MAX_TRIES} times; handed back to the queue")
            self.save()
            self.cond.notify_all()

    def give_back(self, index: int, task: Task) -> None:
        """A step its worker could not start (its server would not come back): to the others, not a try."""
        with self.cond:
            self.busy.pop(index, None)
            (self.highs if task.phase == "high" else self.lows).insert(0, task.job)
            self.cond.notify_all()

    def death(self, index: int) -> None:
        """A server died; after SOLO_DEATHS within SOLO_WINDOW, only one ComfyUI stays on the host."""
        with self.cond:
            now = self.clock()
            self.deaths.append(now)
            recent = [d for d in self.deaths if now - d <= SOLO_WINDOW]
            if not self.solo and len(self.alive) > 1 and len(recent) >= SOLO_DEATHS:
                self.solo = True
                log(f"{len(recent)} server deaths in {SOLO_WINDOW / 60:.0f} min: one ComfyUI on the host from now on")
                self.cond.notify_all()

    def retire(self, index: int) -> None:
        with self.cond:
            self.alive.discard(index)
            self.busy.pop(index, None)
            if not self.alive:
                for job in self.highs + self.lows:
                    job["_record"].update(ok=False, error="no ComfyUI server left to run it", error_kind="server",
                                          finished_at=now_iso())
                self.highs, self.lows = [], []
                self.save()
            self.cond.notify_all()


def recover(worker) -> bool:
    """Restart a worker's server, RESTART_TRIES times at most; False when it would not come back."""
    for n in range(1, RESTART_TRIES + 1):
        try:
            worker.restart()
            return True
        except Exception as err:  # noqa: BLE001
            log(f"ComfyUI {worker.index}: restart {n} of {RESTART_TRIES} failed ({err})")
            time.sleep(RESTART_PAUSE * n)
    return False


def work(worker, plan: Work, steps: dict, clock=time.time) -> None:
    """One GPU's loop: take a step, run it; when the infrastructure fails under it, restart the server and let the
    step be tried again (by any worker). A worker whose server will not come back gives its GPU up."""
    while True:
        task = plan.take(worker.index)
        if task is None:
            break
        if worker.phase not in (None, task.phase):  # the other expert is loaded: out of the GPU and the RAM
            try:
                worker.free()
            except Exception as err:  # noqa: BLE001
                log(f"ComfyUI {worker.index}: free failed ({err}); restarting it")
                if worker.dead():
                    plan.death(worker.index)
                if not recover(worker):
                    plan.give_back(worker.index, task)
                    plan.retire(worker.index)
                    break
        worker.phase = task.phase
        t = clock()
        try:
            file = steps[task.phase](worker, task.job)
        except StillError as err:
            plan.failed(worker.index, task, err, clock() - t, kind="input")
            continue
        except Exception as err:  # noqa: BLE001
            kind = infra_kind(err, worker)
            if kind is None:
                plan.failed(worker.index, task, err, clock() - t)
                continue
            if worker.dead():
                plan.death(worker.index)
            plan.lost(worker.index, task, err, kind, clock() - t)
            if not recover(worker):
                log(f"ComfyUI {worker.index} would not come back: its GPU is given up")
                plan.retire(worker.index)
                break
            continue
        plan.done(worker.index, task, clock() - t, file)
    worker.stop()


class StillError(RuntimeError):
    """A job's still could not be read: it never reached the model (error_kind input)."""


def clip_steps(files: dict, input_dir: Path) -> dict:
    """The two steps of a clip on a worker: high-noise steps to a latent, low-noise steps + decode to <clip>.mp4."""

    def high(worker: Worker, job: dict) -> None:
        rec = job["_record"]
        if "_stills" not in job:
            try:
                job["_stills"] = prepare_stills(job, input_dir)
            except Exception as err:  # noqa: BLE001 - the still never reached the model
                raise StillError(f"could not read the still(s): {err}") from err
        names, size = job["_stills"]
        frames = frame_count(job["mode"], float(job["duration"]))
        rec.update(gpu=worker.index, width=size[0], height=size[1], frames=frames,
                   switch_step=switch_step(int(job["steps"]), PROFILES[job["mode"]]["shift"]))
        log(f"{job['clip']}: high-noise steps on GPU {worker.index} (host RAM {_gb(host_ram_gb())} free)")
        outputs = worker.run(high_graph(job, files, names, size, frames, f"latents/{job['clip']}"))
        rec["high_ram_min_gb"] = worker.ram_min
        latent = outputs["save"]["latents"][0]
        source = worker.output / latent.get("subfolder", "") / latent["filename"]
        shutil.move(str(source), input_dir / f"{job['clip']}.latent")
        return None

    def low(worker: Worker, job: dict) -> str:
        rec = job["_record"]
        names, size = job["_stills"]
        frames = rec["frames"]
        rec["low_gpu"] = worker.index
        log(f"{job['clip']}: low-noise steps on GPU {worker.index} (host RAM {_gb(host_ram_gb())} free)")
        outputs = worker.run(low_graph(job, files, names, size, frames, f"{job['clip']}.latent", f"frames/{job['clip']}"))
        rec["low_ram_min_gb"] = worker.ram_min
        images = outputs["decode" if "decode" in outputs else "save"]["images"]
        paths = [worker.output / i.get("subfolder", "") / i["filename"] for i in images]
        if blank(paths):
            raise RuntimeError("the decoded frames are blank (fp16 overflow?)")
        encode(paths, OUT / f"{job['clip']}.mp4")
        for path in paths:
            path.unlink()
        return f"{job['clip']}.mp4"

    return {"high": high, "low": low}


def on_server(worker: Worker, job: dict, what: str, step):
    """Run one ComfyUI step; when the infrastructure fails under it, restart the server and try again
    (MAX_TRIES in all for the job)."""
    for n in range(1, MAX_TRIES + 1):
        try:
            return step()
        except Exception as err:  # noqa: BLE001
            if infra_kind(err, worker) is None or n == MAX_TRIES:
                raise
            log(f"{job['clip']}: ComfyUI {worker.index} lost during the {what} ({err}); restarting it and retrying")
            worker.restart()
    raise AssertionError("unreachable")


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    job_list = load_jobs()
    jobs = [dict(j) for j in job_list["jobs"]]
    for job in jobs:
        if job["mode"] not in (*MODES, EDIT_MODE):
            raise SystemExit(f"{job['clip']}: unknown mode {job['mode']}")
    edit_jobs = [j for j in jobs if j["mode"] == EDIT_MODE]
    clip_jobs = [j for j in jobs if j["mode"] != EDIT_MODE]
    cards = gpus()
    log(f"menga kernel v{KERNEL_VERSION}: {len(jobs)} job(s); GPUs: {cards or 'none'}; python {sys.version.split()[0]}")
    try:
        import torch  # type: ignore[import-not-found]  # noqa: PLC0415

        log(f"torch {torch.__version__}, CUDA {torch.version.cuda}")
    except ImportError:
        pass
    manifest = Manifest({
        "kernel_version": KERNEL_VERSION, "export": {k: v for k, v in job_list.items() if k != "jobs"},
        "started_at": now_iso(), "comfyui": COMFYUI["name"], "gguf_node": GGUF_NODE["name"],
        "model": MODEL_NAME, "models": {r: f"{m[0]}@{m[1]}/{m[2]}" for r, m in MODELS.items()},
        "lora_strength": {"high": LORA_HIGH, "low": LORA_LOW}, "profiles": PROFILES, "gpus": cards,
        "jobs": [],
    })
    if edit_jobs:
        manifest.data.update(edit_model=EDIT_MODEL_NAME, edit_models={})
    for job in jobs:
        job["_record"] = {k: job[k] for k in ("clip", "shot", "candidate", "attempt", "mode", "strategy", "seed",
                                              "steps", "duration", "stills") if k in job}
        manifest.data["jobs"].append(job["_record"])
    manifest.save()
    if not cards:
        raise SystemExit("no GPU: push with --accelerator NvidiaTeslaT4 (GPU T4 x2)")

    root = work_dir()
    root.mkdir(parents=True, exist_ok=True)
    holder: dict = {}

    def install() -> None:
        try:
            holder["comfy"] = install_comfyui(root)
        except Exception as err:  # noqa: BLE001
            holder["error"] = err

    t = time.time()
    installer = threading.Thread(target=install)
    installer.start()
    models_root = root / "models-dl"
    files = edit_files = None
    if edit_jobs:  # the image edits first (cell-v2 19); their models only when the run has edit jobs
        try:
            edit_files = download_models(models_root, EDIT_MODELS, manifest.data["edit_models"])
        except Exception as err:  # noqa: BLE001 - the edits never reach the model; the clips still run
            log(f"image-edit models not fetched: {err}")
            shutil.rmtree(models_root, ignore_errors=True)  # room for the clip models
            for job in edit_jobs:
                job["_record"].update(ok=False, error=f"image-edit models not fetched: {err}", error_kind="setup",
                                      finished_at=now_iso())
        manifest.save()
    elif clip_jobs:
        files = download_models(models_root)
    installer.join()
    if "error" in holder:
        raise holder["error"]
    comfy = holder["comfy"]
    workers: list[Worker] = []
    try:
        if edit_files is not None:
            try:  # whatever goes wrong here, the clips still run
                link_models(comfy, models_root, EDIT_MODELS)
                log(f"ComfyUI and image-edit models ready in {time.time() - t:.0f}s")
                editor = Worker(0, comfy, root)  # GPU 0 alone: the edit model and the clip models never share the RAM
                workers.append(editor)
                editor.wait_ready()
                manifest.data["edit_setup_seconds"] = round(time.time() - _T0, 1)
                run_edits(editor, edit_jobs, edit_files, manifest)
            except Exception as err:  # noqa: BLE001 - jobs it never ran did not reach the model
                log(f"image-edit phase failed: {err}")
                for job in edit_jobs:
                    if "ok" not in job["_record"]:
                        job["_record"].update(ok=False, error=f"image-edit phase failed: {err}", error_kind="setup",
                                              finished_at=now_iso())
                manifest.save()
            for w in workers:
                w.stop()
            workers = []
            edit_log = root / "comfyui0.log"
            if edit_log.is_file():  # the clips' GPU 0 server starts a new log
                tail = edit_log.read_text(errors="replace").splitlines()[-60:]
                (OUT / "comfyui-edit.log").write_text("\n".join(tail) + "\n")
            drop_models(comfy, models_root, edit_files, EDIT_MODELS)
        if clip_jobs:
            if files is None:
                files = download_models(models_root)
            link_models(comfy, models_root, MODELS)
            log(f"ComfyUI and models ready in {time.time() - t:.0f}s; host RAM {_gb(host_ram_gb())} free")
            shared = root / "in"  # stills and latents: any worker can take any job's next step
            workers = [Worker(i, comfy, root, shared) for i in range(min(len(cards), len(clip_jobs)) or 1)]
            ready = []
            for w in workers:
                try:
                    w.wait_ready()
                    ready.append(w)
                except Exception as err:  # noqa: BLE001
                    log(f"ComfyUI {w.index} did not start ({err}); restarting it")
                    if recover(w):
                        ready.append(w)
                    else:
                        w.stop()
            setup = time.time() - _T0
            manifest.data["setup_seconds"] = round(setup, 1)
            hours = min(float(job_list.get("hours") or SESSION_CAP_HOURS), SESSION_CAP_HOURS)
            manifest.data["hours"] = hours
            manifest.save()
            log(f"setup done in {setup:.0f}s; {len(ready)} worker(s); steps that cannot end by {hours:g} h are not started")
            plan = Work(clip_jobs, [w.index for w in ready], _T0 + hours * 3600, save=manifest.save)
            if not ready:
                plan.retire(-1)
            steps = clip_steps(files, shared)
            threads = [threading.Thread(target=work, args=(w, plan, steps)) for w in ready]
            for th in threads:
                th.start()
            for th in threads:
                th.join()
            manifest.data["restarts"] = {str(w.index): w.restarts for w in workers}
    finally:
        for w in workers:
            w.stop()
        for i in range(len(cards) or 1):
            log_path = root / f"comfyui{i}.log"
            if log_path.is_file():  # without LoRA key noise, so restarts and the last errors fit
                lines = [x for x in log_path.read_text(errors="replace").splitlines() if "lora key not loaded" not in x]
                (OUT / f"comfyui{i}.log").write_text("\n".join(lines[-400:]) + "\n")
        manifest.data["finished_at"] = now_iso()
        manifest.data["session_seconds"] = round(time.time() - _T0, 1)
        manifest.save()
    made = sum(1 for j in jobs if j["_record"].get("ok"))
    log(f"finished: {made}/{len(jobs)} clip(s) in {time.time() - _T0:.0f}s")


if __name__ == "__main__" or os.environ.get("KAGGLE_KERNEL_RUN_TYPE"):
    if os.environ.get("MENGA_KERNEL_NO_RUN") != "1":
        main()
